PROGRAM ST470_MIGSVETSCELL
VAR
    steg        : INT := 0;
    tmrGasFor   : TON;
    tmrEfter    : TON;
    tmrTand     : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xGasFor     : BOOL := FALSE;
    xEfterflode : BOOL := FALSE;
    xTandning   : BOOL := FALSE;
    xIlage      : BOOL := FALSE;
    xBage       : BOOL := FALSE; (* sekvensens kommando: bagen tand *)
    xTrad       : BOOL := FALSE; (* sekvensens kommando: tradmatning *)
    xIndex      : BOOL := FALSE; (* sekvensens kommando: indexera bordet *)
END_VAR

(* EMG_OK och ST470_LGT_CLEAR kommer fran sakerhets-PLC:n och lases bara.
   Logiken har ror ingen sakerhetsfunktion; den ar forreglad AV dem. *)
trigReset(CLK := SYS_RESET);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Tidsuren stalls ur foregaende scans steg, sa PT gar att lasa som en tid och
   inte som ett antal scan. *)
xGasFor := (steg = 2);
xEfterflode := (steg = 5);
xTandning := ST470_ARC_ON AND NOT ST470_ARC_OK;
tmrGasFor(IN := xGasFor, PT := T#800ms);
tmrEfter(IN := xEfterflode, PT := T#1500ms);
tmrTand(IN := xTandning, PT := T#1000ms);

(* Tandfel: uteblir ST470_ARC_OK inom 1,0 s efter kommendering matas trad
   rakt in i fogen utan att smalta. Gas, trad och bage ska av. *)
IF tmrTand.Q THEN
    xLarm := TRUE;
END_IF;

(* Svetsstrommen utanfor 210,0 till 260,0 A medan bagen brinner: for lite
   intrangning i 6 mm plat, eller genombranning. *)
IF ST470_ARC_OK AND (ST470_ARC_CUR < 210.0 OR ST470_ARC_CUR > 260.0) THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET. Att slappa upp
   nodstoppsdonet eller att tryckluften kommer tillbaka startar ingenting. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;
xIlage := ST470_TBL_POS_A OR ST470_TBL_POS_B;

IF NOT xDriftsklar THEN
    xBage := FALSE;
    xTrad := FALSE;
    ST470_GAS_ON := FALSE;
    xIndex := FALSE;
    ST470_CLP_CLOSE := FALSE;
    ST470_RB_START := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            (* Fixturen spanns nar bordet star i ett indexlage och
               ljusridan pa operatorssidan ar obruten. *)
            IF xIlage AND ST470_LGT_CLEAR AND NOT ST470_CLP_CLOSED THEN
                ST470_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;
        1:
            IF ST470_CLP_CLOSED THEN
                ST470_GAS_ON := TRUE;
                steg := 2;
            END_IF;
        2:
            (* Bagen tands forst nar gasforflodet 0,8 s runnit ut. *)
            IF tmrGasFor.Q AND ST470_LGT_CLEAR AND ST470_CLP_CLOSED THEN
                xTrad := TRUE;
                xBage := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST470_ARC_OK THEN
                ST470_RB_START := TRUE;
                steg := 4;
            END_IF;
        4:
            IF ST470_RB_DONE THEN
                xBage := FALSE;
                xTrad := FALSE;
                ST470_RB_START := FALSE;
                steg := 5;
            END_IF;
        5:
            (* Efterflodet 1,5 s: en smalta som svalnar utan skyddsgas
               oxiderar och fogen far porer i ytan. *)
            IF tmrEfter.Q THEN
                ST470_GAS_ON := FALSE;
                steg := 6;
            END_IF;
        6:
            IF ST470_LGT_CLEAR THEN
                xIndex := TRUE;
                steg := 7;
            END_IF;
        7:
            IF NOT xIlage THEN
                steg := 8;
            END_IF;
        8:
            IF xIlage THEN
                xIndex := FALSE;
                ST470_CLP_CLOSE := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Forreglingarna ligger efter sekvensen och skrivs som villkor pa utgangen:
   varje utgang har ETT skrivstalle, och det som far den att falla star i
   samma uttryck som det som far den att ga. Bage och trad bara med gas;
   bordet indexerar aldrig med bagen tand eller ridan bruten. *)
ST470_ARC_ON := xBage AND ST470_GAS_ON;
ST470_WIR_FEED := xTrad AND ST470_GAS_ON;
ST470_TBL_INDEX := xIndex AND NOT ST470_ARC_ON AND ST470_LGT_CLEAR;
END_PROGRAM

